    <template v-if="active==='summary'">
      <div class="metric-grid"><div class="metric-card"><span>仓库</span><strong>{{summary.warehouse_count||0}}</strong><small>启用的备件仓库</small></div><div class="metric-card"><span>库存SKU</span><strong>{{summary.stock_skus||0}}</strong><small>总数量 {{summary.stock_quantity||0}}</small></div><div class="metric-card"><span>补货/超储预警</span><strong>{{summary.reorder_alerts||0}} / {{summary.excess_alerts||0}}</strong><small>参数驱动而非人工判断</small></div><div class="metric-card"><span>保养/呆滞候选</span><strong>{{summary.soh_alerts||0}} / {{summary.dormant_candidates||0}}</strong><small>SOH与流动性联合识别</small></div></div>
      <div class="chart-grid"><div class="chart-card"><h3>库存风险构成</h3><AnalysisChart :option="riskChart"/></div><div class="chart-card"><h3>数字化预警</h3><el-table :data="summary.alerts||[]" max-height="280" empty-text="当前没有预警"><el-table-column prop="type" label="类型" width="80"/><el-table-column prop="material_code" label="物料"/><el-table-column prop="warehouse_code" label="仓库"/><el-table-column prop="message" label="规则命中" min-width="180"/></el-table></div></div>
      <el-alert title="数字化接口边界：ERP/WMS提供收发存和业务单据，EAM/MES提供维护需求，IoT提供温湿度/振动等状态；本模块保存来源系统并形成可追溯预警，不用采购记录替代真实领用数据。" type="info" :closable="false"/>
    </template>

    <template v-else-if="active==='lifecycle'">
      <el-alert title="生命周期主线：采购/收货 → 入库批次 → 保养与盘点 → 领用/移库 → 报废或回收；每个节点保留来源系统、批次与业务单号。" type="success" :closable="false"/>
      <el-table :data="summary.lifecycle||[]" class="data-table" style="margin-top:18px"><el-table-column prop="material_code" label="物料编码"/><el-table-column prop="batch_no" label="批次"/><el-table-column prop="status" label="生命周期状态"/><el-table-column prop="source_system" label="来源系统"/><el-table-column prop="received_date" label="入库日期"/><el-table-column prop="last_issue_date" label="最近领用"/><el-table-column prop="expiry_date" label="失效日期"/></el-table>
    </template>

    <template v-else>
      <div class="table-toolbar"><el-input v-model.trim="keyword" clearable placeholder="编码、名称、物料或业务单号" @keyup.enter.native="search" @clear="search"/><el-select v-if="active==='warehouse-locations'||active==='spare-stocks'" v-model="warehouseFilter" clearable placeholder="全部仓库" @change="search"><el-option v-for="w in warehouses" :key="w.code" :label="w.name" :value="w.code"/></el-select><el-select v-if="active==='spare-stocks'" v-model="conditionFilter" clearable placeholder="全部SOH状态" @change="search"><el-option label="良好" value="good"/><el-option label="需关注" value="attention"/><el-option label="隔离" value="quarantine"/><el-option label="损坏" value="damaged"/></el-select><el-button icon="el-icon-search" @click="search">查询</el-button></div>
      <el-table v-loading="loading" :data="items" class="data-table" :empty-text="`暂无${activeName}`">
        <template v-if="active==='warehouses'"><el-table-column prop="code" label="仓库编码"/><el-table-column prop="name" label="仓库名称"/><el-table-column prop="factory_code" label="工厂"/><el-table-column prop="manager" label="负责人"/><el-table-column prop="maintenance_distance_m" label="距维修区(m)"/><el-table-column label="状态"><template slot-scope="s">{{s.row.active?'启用':'停用'}}</template></el-table-column></template>
        <template v-else-if="active==='warehouse-locations'"><el-table-column prop="warehouse_code" label="仓库"/><el-table-column prop="code" label="库位"/><el-table-column prop="name" label="名称"/><el-table-column label="布局策略"><template slot-scope="s"><el-tag>{{zoneName(s.row.zone_type)}}</el-tag><el-tag v-if="s.row.near_maintenance" type="success">近维修区</el-tag><el-tag v-if="s.row.heavy_duty" type="warning">重载</el-tag></template></el-table-column><el-table-column prop="humidity_limit" label="湿度上限%"/></template>
        <template v-else-if="active==='spare-stocks'"><el-table-column prop="material_code" label="物料编码" width="135"/><el-table-column prop="material_name" label="名称"/><el-table-column prop="warehouse_code" label="仓库" width="100"/><el-table-column prop="location_code" label="库位" width="100"/><el-table-column prop="batch_no" label="批次"/><el-table-column prop="quantity" label="现存"/><el-table-column label="库存参数" min-width="210"><template slot-scope="s">安{{s.row.safety_stock}} / 低{{s.row.min_stock}} / 订{{s.row.reorder_point}} / 高{{s.row.max_stock}}</template></el-table-column><el-table-column label="预警" width="90"><template slot-scope="s"><el-tag :type="stockTag(s.row)">{{stockState(s.row)}}</el-tag></template></el-table-column><el-table-column label="SOH"><template slot-scope="s">{{conditionName(s.row.condition)}}</template></el-table-column></template>
        <template v-else-if="active==='warehouse-movements'"><el-table-column prop="movement_no" label="流水号"/><el-table-column label="类型"><template slot-scope="s">{{movementName(s.row.movement_type)}}</template></el-table-column><el-table-column prop="material_code" label="物料"/><el-table-column label="路径"><template slot-scope="s">{{s.row.from_location||'外部'}} → {{s.row.to_location||'外部'}}</template></el-table-column><el-table-column prop="quantity" label="数量"/><el-table-column prop="business_no" label="业务单号"/><el-table-column prop="operator" label="操作人"/><el-table-column prop="happened_at" label="时间"/></template>
        <template v-else-if="active==='stocktakes'"><el-table-column prop="material_code" label="物料"/><el-table-column prop="warehouse_code" label="仓库"/><el-table-column prop="book_quantity" label="账面"/><el-table-column prop="counted_quantity" label="实盘"/><el-table-column label="差异"><template slot-scope="s"><strong :style="{color:Number(s.row.variance)?'#d92d20':'#12b76a'}">{{s.row.variance}}</strong></template></el-table-column><el-table-column prop="reason" label="差异原因"/><el-table-column prop="counted_by" label="盘点人"/><el-table-column prop="counted_at" label="盘点时间"/></template>
        <template v-else><el-table-column prop="stock_id" label="库存记录"/><el-table-column label="防锈/防潮/防尘/包装"><template slot-scope="s">{{s.row.rust_score}} / {{s.row.moisture_score}} / {{s.row.dust_score}} / {{s.row.packaging_score}}</template></el-table-column><el-table-column label="结论"><template slot-scope="s"><el-tag :type="s.row.conclusion==='good'?'success':s.row.conclusion==='attention'?'warning':'danger'">{{conditionName(s.row.conclusion)}}</el-tag></template></el-table-column><el-table-column prop="action" label="处置措施"/><el-table-column prop="inspected_by" label="检查人"/><el-table-column prop="inspected_at" label="时间"/></template>
        <el-table-column v-if="['warehouses','warehouse-locations','spare-stocks'].includes(active)" label="操作" width="125" fixed="right"><template slot-scope="s"><el-button type="text" @click="open(s.row)">编辑</el-button><el-button type="text" class="danger-link" @click="remove(s.row)">删除</el-button></template></el-table-column>
      </el-table>
      <div class="pagination-row"><span>共 {{pagination.total}} 条</span><el-pagination background layout="sizes, prev, pager, next" :page-sizes="[10,20,50]" :current-page="pagination.page" :page-size="pagination.page_size" :total="pagination.total" @current-change="changePage" @size-change="changeSize"/></div>
    </template>

