      <template v-else-if="active==='warehouse-locations'"><el-row :gutter="16"><el-col :span="12"><el-form-item label="仓库"><el-select v-model="form.warehouse_code" style="width:100%"><el-option v-for="w in warehouses" :key="w.code" :label="w.name" :value="w.code"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="库位编码"><el-input v-model.trim="form.code"/></el-form-item></el-col></el-row><el-row :gutter="16"><el-col :span="12"><el-form-item label="库位名称"><el-input v-model.trim="form.name"/></el-form-item></el-col><el-col :span="12"><el-form-item label="区域类型"><el-select v-model="form.zone_type" style="width:100%"><el-option label="高频区" value="fast"/><el-option label="普通区" value="normal"/><el-option label="重型区" value="heavy"/><el-option label="关键件区" value="critical"/><el-option label="隔离区" value="quarantine"/></el-select></el-form-item></el-col></el-row><el-form-item label="布局属性"><el-checkbox v-model="form.near_maintenance">靠近维修区</el-checkbox><el-checkbox v-model="form.heavy_duty">重型承载</el-checkbox><el-checkbox v-model="form.temperature_controlled">温湿度控制</el-checkbox></el-form-item><el-form-item label="湿度上限"><el-input-number v-model="form.humidity_limit" :min="0" :max="100"/></el-form-item></template>
      <template v-else-if="active==='spare-stocks'"><el-row :gutter="16"><el-col :span="12"><el-form-item label="仓库"><el-select v-model="form.warehouse_code" style="width:100%" @change="form.location_code=''" ><el-option v-for="w in warehouses" :key="w.code" :label="w.name" :value="w.code"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="库位"><el-select v-model="form.location_code" style="width:100%"><el-option v-for="l in selectedLocations" :key="l.code" :label="`${l.code} · ${l.name}`" :value="l.code"/></el-select></el-form-item></el-col></el-row><el-row :gutter="16"><el-col :span="12"><el-form-item label="备件物料"><el-select v-model="form.material_code" filterable style="width:100%" @change="selectMaterial"><el-option v-for="m in materials" :key="m.code" :label="`${m.code} · ${m.name}`" :value="m.code"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="批次"><el-input v-model.trim="form.batch_no"/></el-form-item></el-col></el-row><el-alert title="参数约束：安全库存 ≤ 最低库存 ≤ 再订货点 ≤ 最高库存；计划性储备用于维修计划，不等同于额外采购数量。" type="info" :closable="false"/><el-row :gutter="8" style="margin-top:16px"><el-col v-for="field in stockFields" :key="field.key" :span="8"><el-form-item :label="field.label"><el-input-number v-model="form[field.key]" :min="0" :precision="2" style="width:100%"/></el-form-item></el-col></el-row><el-row :gutter="16"><el-col :span="12"><el-form-item label="SOH状态"><el-select v-model="form.condition" style="width:100%"><el-option label="良好" value="good"/><el-option label="需关注" value="attention"/><el-option label="隔离" value="quarantine"/><el-option label="损坏" value="damaged"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="来源系统"><el-input v-model.trim="form.source_system" placeholder="manual / ERP / WMS / IoT"/></el-form-item></el-col></el-row></template>
      <template v-else-if="active==='warehouse-movements'"><el-form-item label="业务类型"><el-radio-group v-model="form.movement_type"><el-radio-button label="receipt">入库</el-radio-button><el-radio-button label="issue">领用</el-radio-button><el-radio-button label="return">退回</el-radio-button><el-radio-button label="transfer">移库</el-radio-button><el-radio-button label="scrap">报废</el-radio-button><el-radio-button label="recycle">回收</el-radio-button></el-radio-group></el-form-item><el-row :gutter="16"><el-col :span="12"><el-form-item label="仓库"><el-select v-model="form.warehouse_code" style="width:100%"><el-option v-for="w in warehouses" :key="w.code" :label="w.name" :value="w.code"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="物料"><el-select v-model="form.material_code" filterable style="width:100%" @change="selectMaterial"><el-option v-for="m in materials" :key="m.code" :label="`${m.code} · ${m.name}`" :value="m.code"/></el-select></el-form-item></el-col></el-row><el-row :gutter="16"><el-col :span="12"><el-form-item label="来源库位"><el-input v-model.trim="form.from_location"/></el-form-item></el-col><el-col :span="12"><el-form-item label="目标库位"><el-input v-model.trim="form.to_location"/></el-form-item></el-col></el-row><el-row :gutter="16"><el-col :span="8"><el-form-item label="批次"><el-input v-model.trim="form.batch_no"/></el-form-item></el-col><el-col :span="8"><el-form-item label="数量"><el-input-number v-model="form.quantity" :min="0.01" style="width:100%"/></el-form-item></el-col><el-col :span="8"><el-form-item label="业务单号"><el-input v-model.trim="form.business_no"/></el-form-item></el-col></el-row></template>
      <template v-else-if="active==='stocktakes'"><el-form-item label="库存记录"><el-select v-model="form.stock_id" filterable style="width:100%"><el-option v-for="s in stocks" :key="s.id" :label="`${s.material_code} · ${s.warehouse_code}/${s.location_code} · 账面${s.quantity}`" :value="s.id"/></el-select></el-form-item><el-form-item label="实盘数量"><el-input-number v-model="form.counted_quantity" :min="0" :precision="2" style="width:100%"/></el-form-item><el-form-item label="差异原因"><el-input v-model="form.reason" type="textarea" :rows="3"/></el-form-item></template>
      <template v-else><el-form-item label="库存记录"><el-select v-model="form.stock_id" filterable style="width:100%"><el-option v-for="s in stocks" :key="s.id" :label="`${s.material_code} · ${s.warehouse_code}/${s.location_code}`" :value="s.id"/></el-select></el-form-item><el-alert title="SOH监督：100表示状态最佳；系统按防锈、防潮、防尘和包装四项均值自动给出良好、关注或隔离结论。" type="info" :closable="false"/><el-row :gutter="8" style="margin-top:16px"><el-col v-for="f in sohFields" :key="f.key" :span="6"><el-form-item :label="f.label"><el-input-number v-model="form[f.key]" :min="0" :max="100" style="width:100%"/></el-form-item></el-col></el-row><el-form-item label="处置措施"><el-input v-model="form.action" type="textarea" :rows="3"/></el-form-item></template>
    </el-form><span slot="footer"><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存并执行</el-button></span></el-dialog>
  </div>
</template>
<script>
import {api} from '../api/client';import AnalysisChart from '../components/AnalysisChart.vue';
const forms={warehouses:()=>({code:'',name:'',factory_code:'',address:'',manager:'',maintenance_distance_m:0,active:true,version:1}),'warehouse-locations':()=>({warehouse_code:'',code:'',name:'',zone_type:'normal',near_maintenance:false,heavy_duty:false,temperature_controlled:false,humidity_limit:70,active:true,version:1}),'spare-stocks':()=>({warehouse_code:'',location_code:'',material_code:'',material_name:'',batch_no:'',quantity:0,safety_stock:0,min_stock:0,max_stock:0,reorder_point:0,planned_reserve:0,condition:'good',lifecycle_status:'in_stock',received_date:null,last_issue_date:null,expiry_date:null,source_system:'manual',version:1}),'warehouse-movements':()=>({movement_type:'receipt',warehouse_code:'',from_location:'',to_location:'',material_code:'',material_name:'',batch_no:'',quantity:1,business_no:''}),stocktakes:()=>({stock_id:'',counted_quantity:0,reason:''}),'soh-inspections':()=>({stock_id:'',rust_score:100,moisture_score:100,dust_score:100,packaging_score:100,action:''})};
export default {components:{AnalysisChart},data:()=>({active:'summary',items:[],warehouses:[],locations:[],stocks:[],materials:[],summary:{},loading:false,saving:false,visible:false,keyword:'',warehouseFilter:'',conditionFilter:'',form:{},pagination:{page:1,page_size:10,total:0},stockFields:[{key:'quantity',label:'现存数量'},{key:'safety_stock',label:'安全库存'},{key:'min_stock',label:'最低库存'},{key:'reorder_point',label:'再订货点'},{key:'max_stock',label:'最高库存'},{key:'planned_reserve',label:'计划性储备'}],sohFields:[{key:'rust_score',label:'防锈'},{key:'moisture_score',label:'防潮'},{key:'dust_score',label:'防尘'},{key:'packaging_score',label:'包装'}]}),computed:{activeName(){return {warehouses:'仓库档案','warehouse-locations':'库位','spare-stocks':'库存策略','warehouse-movements':'收发退流水',stocktakes:'盘点记录','soh-inspections':'SOH检查'}[this.active]||'';},createName(){return {warehouses:'新建仓库','warehouse-locations':'新建库位','spare-stocks':'新建库存策略','warehouse-movements':'登记收发退/移库',stocktakes:'执行盘点','soh-inspections':'执行SOH检查'}[this.active]||'';},canCreate(){return !['summary','lifecycle'].includes(this.active);},selectedLocations(){return this.locations.filter(l=>l.warehouse_code===this.form.warehouse_code);},riskChart(){const s=this.summary;return {tooltip:{trigger:'axis'},grid:{left:65,right:20,bottom:40},xAxis:{type:'category',data:['低于订货点','超过最高库存','SOH异常','呆滞候选']},yAxis:{type:'value',minInterval:1},series:[{type:'bar',data:[s.reorder_alerts||0,s.excess_alerts||0,s.soh_alerts||0,s.dormant_candidates||0],itemStyle:{color:'#2878ff'}}]};}},created(){this.loadReference();this.loadSummary();},methods:{error(e){this.$message.error(e.response?.data?.detail||e.message||'操作失败');},zoneName(v){return {fast:'高频区',normal:'普通区',heavy:'重型区',critical:'关键件区',quarantine:'隔离区'}[v]||v;},conditionName(v){return {good:'良好',attention:'需关注',quarantine:'隔离',damaged:'损坏'}[v]||v;},movementName(v){return {receipt:'入库',issue:'领用',return:'退回',transfer:'移库',scrap:'报废',recycle:'回收'}[v]||v;},stockState(r){if(r.condition!=='good')return 'SOH异常';if(Number(r.quantity)<=Number(r.reorder_point))return '需补货';if(Number(r.max_stock)>0&&Number(r.quantity)>Number(r.max_stock))return '超储';return '正常';},stockTag(r){return this.stockState(r)==='正常'?'success':this.stockState(r)==='超储'?'warning':'danger';},async loadReference(){try{const [w,l,s,m]=await Promise.all([api.get('/warehouses',{params:{page:1,page_size:100}}),api.get('/warehouse-locations',{params:{page:1,page_size:100}}),api.get('/spare-stocks',{params:{page:1,page_size:100}}),api.get('/materials',{params:{material_type:'spare',page:1,page_size:100}})]);this.warehouses=w.data.items;this.locations=l.data.items;this.stocks=s.data.items;this.materials=m.data.items;}catch(e){this.error(e);}},async loadSummary(){try{this.summary=(await api.get('/warehouse/summary')).data;}catch(e){this.error(e);}},async load(){if(['summary','lifecycle'].includes(this.active))return this.loadSummary();this.loading=true;try{const params={keyword:this.keyword,page:this.pagination.page,page_size:this.pagination.page_size};if(this.warehouseFilter)params.warehouse_code=this.warehouseFilter;if(this.conditionFilter)params.condition=this.conditionFilter;const r=(await api.get('/'+this.active,{params})).data;this.items=r.items;this.pagination.total=r.total;}catch(e){this.error(e);}finally{this.loading=false;}},changeTab(){this.keyword='';this.pagination.page=1;if(this.active==='summary'||this.active==='lifecycle')this.loadSummary();else this.load();},search(){this.pagination.page=1;this.load();},changePage(v){this.pagination.page=v;this.load();},changeSize(v){this.pagination.page_size=v;this.pagination.page=1;this.load();},open(row){this.form=row?JSON.parse(JSON.stringify(row)):forms[this.active]();Object.keys(this.form).forEach(k=>{if(['quantity','safety_stock','min_stock','max_stock','reorder_point','planned_reserve','maintenance_distance_m','humidity_limit'].includes(k))this.form[k]=Number(this.form[k]);});this.visible=true;},selectMaterial(code){const m=this.materials.find(x=>x.code===code);if(m)this.form.material_name=m.name;},async save(){const required=this.active==='warehouses'?['code','name']:this.active==='warehouse-locations'?['warehouse_code','code']:this.active==='spare-stocks'?['warehouse_code','location_code','material_code']:this.active==='warehouse-movements'?['warehouse_code','material_code']:['stock_id'];if(required.some(k=>!this.form[k]))return this.$message.warning('请填写必填字段');this.saving=true;try{const endpoint='/'+this.active;if(this.form.id)await api.put(endpoint+'/'+this.form.id,this.form);else await api.post(endpoint,this.form);this.$message.success('已保存并更新关联数据');this.visible=false;await Promise.all([this.load(),this.loadReference(),this.loadSummary()]);}catch(e){this.error(e);}finally{this.saving=false;}},async remove(row){try{await this.$confirm('删除该记录？有关联库存或非零库存时系统将拒绝。','确认');await api.delete('/'+this.active+'/'+row.id,{params:{version:row.version}});this.$message.success('已删除');await Promise.all([this.load(),this.loadReference(),this.loadSummary()]);}catch(e){if(e!=='cancel')this.error(e);}}}};
</script>
